def can_form_brute(word, word_set):
    def backtrack(start, pieces_used):
        if start == len(word):
            return pieces_used >= 2
        for end in range(start + 1, len(word) + 1):
            piece = word[start:end]
            if piece in word_set:
                if backtrack(end, pieces_used + 1):        # try every possible split point
                    return True
        return False
    return backtrack(0, 0)

