import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEnd = false;
}

public class Main {
    static TrieNode buildTrie(List<String> words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode node = root;
            for (char c : w.toCharArray()) node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.isEnd = true;
        }
        return root;
    }

    static boolean canForm(String word, TrieNode root) {
        int n = word.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 0; i < n; i++) {
            if (!dp[i]) continue;
            TrieNode node = root;
            for (int j = i; j < n; j++) {
                char c = word.charAt(j);
                if (!node.children.containsKey(c)) break;              // no further match possible
                node = node.children.get(c);
                if (node.isEnd && !(i == 0 && j == n - 1)) dp[j + 1] = true;  // exclude whole word as one piece
            }
        }
        return dp[n];
    }

    static List<String> findAllConcatenatedWords(List<String> words) {
        TrieNode root = buildTrie(words);
        List<String> result = new ArrayList<>();
        for (String w : words) if (canForm(w, root)) result.add(w);
        return result;
    }
}

