#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; bool isEnd = false; };

TrieNode* buildTrie(vector<string>& words) {
    TrieNode* root = new TrieNode();
    for (auto& w : words) {
        TrieNode* node = root;
        for (char c : w) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
        }
        node->isEnd = true;
    }
    return root;
}

bool canForm(const string& word, TrieNode* root) {
    int n = word.size();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 0; i < n; i++) {
        if (!dp[i]) continue;
        TrieNode* node = root;
        for (int j = i; j < n; j++) {
            char c = word[j];
            if (!node->children.count(c)) break;                       // no further match possible
            node = node->children[c];
            if (node->isEnd && !(i == 0 && j == n - 1)) dp[j + 1] = true;   // exclude whole word as one piece
        }
    }
    return dp[n];
}

vector<string> findAllConcatenatedWords(vector<string>& words) {
    TrieNode* root = buildTrie(words);
    vector<string> result;
    for (auto& w : words) if (canForm(w, root)) result.push_back(w);
    return result;
}
